/* Generated by safe ES module refactor from the existing js/main.js implementation. */

import { clearCurrentUser, getCurrentUser, persistCurrentUser } from "../core/auth.js";
import { extractErrorMessage, getAuthHeader, handleUserAuthFailure, requestJson } from "../core/api.js";
import { USER_LOGIN_PAGE } from "../core/routing.js";
import { formatDateTime, safeOpenExternal } from "../core/utils.js";
import { hideLoader, showLoader } from "../ui/loader.js";
import { copyTextToClipboard, showMessage } from "../ui/toast.js";

export async function loadUserDash() {
  const currentUser = getCurrentUser();
  if (!currentUser || currentUser.role !== "User") {
    clearCurrentUser();
    window.location.replace(USER_LOGIN_PAGE);
    return;
  }

  const nameEl = document.getElementById("dashUsername");
  const planEl = document.getElementById("dashPlan");
  const expiryEl = document.getElementById("dashExpiry");
  const statusEl = document.getElementById("dashOrderStatus");
  const keyEl = document.getElementById("dashOrderKey");
  const copyBtn = document.getElementById("copyDashKeyBtn");
  const keyStatusEl = document.getElementById("dashKeyStatus");
  const statusCard = document.getElementById("status-card");
  const keyCard = document.getElementById("key-card");
  const downloadBtn = document.getElementById("downloadPanelBtn");

  if (nameEl) nameEl.textContent = String(currentUser.username || "user").toUpperCase();
  if (planEl) planEl.textContent = String(currentUser.plan || "Temp").toUpperCase();
  // 🔒 HIDE CHANGE PASSWORD OPTION FOR FREE USERS
  if (currentUser.plan && currentUser.plan.toLowerCase() === "free") {
    const changeLink = document.querySelector('a[href="change.html"]');
    if (changeLink) changeLink.style.display = "none";
  }

  // yaha tak change password link hide karne ka code hai, iske baad expiry date set karne ka code hai
  if (expiryEl) expiryEl.textContent = currentUser.expiry ? formatDateTime(currentUser.expiry) : "N/A (Temp)";

  try {
    const result = await requestJson("/api/auth/my-order", {
      method: "GET",
      headers: getAuthHeader(),
      retries: 0
    });

    if (handleUserAuthFailure(result.status)) return;
    if (!statusEl || !keyEl) return;

    if (result.status === 404) {
      statusEl.textContent = "NO ACTIVE ORDERS";
      statusEl.className = "stat-value text-xl muted";
      if (statusCard) statusCard.className = "stat-card border-surface";
      if (keyCard) keyCard.className = "stat-card border-surface";
      if (keyStatusEl) {
        keyStatusEl.textContent = "";
        keyStatusEl.className = "badge d-none";
      }
      if (copyBtn) {
        copyBtn.style.display = "none";
        copyBtn.onclick = null;
      }
      if (downloadBtn) {
        downloadBtn.style.display = "none";
        downloadBtn.onclick = null;
      }
      return;
    }

    if (!result.ok || !result.data) {
      statusEl.textContent = "SERVER ERROR";
      statusEl.className = "stat-value text-xl title-danger";
      if (statusCard) statusCard.className = "stat-card border-surface";
      if (keyCard) keyCard.className = "stat-card border-surface";
      if (keyStatusEl) {
        keyStatusEl.textContent = "";
        keyStatusEl.className = "badge d-none";
      }
      if (copyBtn) {
        copyBtn.style.display = "none";
        copyBtn.onclick = null;
      }
      if (downloadBtn) {
        downloadBtn.style.display = "none";
        downloadBtn.onclick = null;
      }
      showMessage(extractErrorMessage(result.data, "Unable to load your dashboard right now."), "error");
      return;
    }

    const liveStatus = String(result.data.status || "Pending");
    const livePlan = String(result.data.plan || currentUser.plan || "Temp");
    const liveExpiry = result.data.expiry || result.data.expiryTime || currentUser.expiry || null;
    const orderKey = String(result.data.key || "");
    const hasIssuedKey = Boolean(orderKey) && !/pending|contact/i.test(orderKey);
    const isApproved = liveStatus.toLowerCase() === "approved";
    const normalizedKeyStatus = Boolean(result.data.isKeyUsed) ? "USED" : "UNUSED";
    const persistedUser = persistCurrentUser({
      ...currentUser,
      token: currentUser.token,
      plan: livePlan,
      expiry: liveExpiry,
      loginTime: currentUser.loginTime
    });

    // 🔥 Naya UI Logic Start 🔥
    const alertBox = document.getElementById("dashboardAlertBox");
    const expiryIcon = document.getElementById("expiryIcon");
    const statusIcon = document.getElementById("statusIcon");

    let isTempOrExpired = false;
    if (
      liveStatus.toLowerCase() === "pending" ||
      normalizedKeyStatus === "UNUSED" ||
      livePlan.toLowerCase() === "temp"
    ) {
      isTempOrExpired = false;
    } else {
      isTempOrExpired =
        !liveExpiry ||
        new Date(liveExpiry).getFullYear() < 2000 ||
        new Date(liveExpiry) < new Date();
    }

    if (persistedUser && planEl) planEl.textContent = livePlan.toUpperCase();
    
    if (expiryEl) {
        expiryEl.textContent = liveExpiry ? formatDateTime(liveExpiry) : "N/A (Pending/Temp)";
        if (expiryIcon) expiryIcon.textContent = isTempOrExpired ? "🔴" : "🟢";
        if (isTempOrExpired && expiryEl) expiryEl.className = "stat-value text-md text-danger";
        else if (expiryEl) expiryEl.className = "stat-value text-md text-success";
    }

    statusEl.textContent = liveStatus.toUpperCase();
    statusEl.className = "stat-value text-xl mb-0";
    keyEl.textContent = hasIssuedKey ? orderKey : "Pending Approval";

    if (statusCard) statusCard.className = `stat-card ${isApproved ? "status-approved-border" : "border-surface"}`;
    if (keyCard) keyCard.className = `stat-card ${isApproved ? "status-approved-border" : "border-surface"}`;
    statusEl.classList.add(isApproved ? "status-approved-text" : "text-warning");

    if (statusIcon) statusIcon.textContent = isApproved ? "✅" : (liveStatus.toLowerCase() === "rejected" ? "❌" : "⏳");

    // Alert Box Show/Hide Logic
    if (alertBox) {
        const alertHeading = document.getElementById("alertHeading");
        if (liveStatus.toLowerCase() === "pending") {
            alertBox.classList.remove("d-none");
            alertBox.className = "alert-box alert-warning";
            document.getElementById("dashboardAlertText").textContent = "Your payment is under review. Please wait for admin approval.";
            if (alertHeading) alertHeading.className = "text-warning mb-5 mt-0";
        } else if (isTempOrExpired && livePlan.toLowerCase() !== "free") {
            alertBox.classList.remove("d-none");
            alertBox.className = "alert-box alert-danger";
            document.getElementById("dashboardAlertText").textContent = "Your subscription has expired. Renew now to regain access.";
            if (alertHeading) alertHeading.className = "text-danger mb-5 mt-0";
        } else {
            alertBox.classList.add("d-none");
        }
    }
    // 🔥 Naya UI Logic End 🔥

    if (keyStatusEl && hasIssuedKey) {
      keyStatusEl.textContent = normalizedKeyStatus;
// ... baaki ka code same rahega copy button aur download button wala
      keyStatusEl.className = `badge ${normalizedKeyStatus === "USED" ? "bad" : "good"} d-inline-flex`;
    } else if (keyStatusEl) {
      keyStatusEl.textContent = "";
      keyStatusEl.className = "badge d-none";
    }

    if (copyBtn && hasIssuedKey) {
      copyBtn.classList.remove("d-none", "hidden-default");
      copyBtn.style.display = "block";
      copyBtn.onclick = () => copyTextToClipboard(orderKey, copyBtn, "Copy Key");
    } else if (copyBtn) {
      copyBtn.classList.add("d-none");
      copyBtn.style.display = "none";
      copyBtn.onclick = null;
    }

    const planSlug = String(result.data.plan || currentUser.plan || "").trim().toLowerCase();
    if (downloadBtn && planSlug && planSlug !== "temp" && isApproved) {
      downloadBtn.style.display = "inline-flex";
      downloadBtn.onclick = async (event) => {
        event.preventDefault();
        showLoader("Fetching secure download...");

        try {
          const downloadResult = await requestJson(`/api/auth/download?plan=${encodeURIComponent(planSlug)}`, {
            method: "GET",
            headers: getAuthHeader(),
            retries: 0
          });

          hideLoader();

          if (handleUserAuthFailure(downloadResult.status)) return;
          if (!downloadResult.ok || !downloadResult.data || !downloadResult.data.url) {
            showMessage("Download is unavailable for this account.", "error");
            return;
          }

          safeOpenExternal(downloadResult.data.url);
        } catch (err) {
          hideLoader();
          showMessage("Download server is unavailable right now.", "error");
        }
      };
    } else if (downloadBtn) {
      downloadBtn.style.display = "none";
      downloadBtn.onclick = null;
    }
  } catch (err) {
    if (statusEl) {
      statusEl.textContent = "ERROR FETCHING";
      statusEl.className = "stat-value text-xl title-danger";
    }
    if (downloadBtn) {
      downloadBtn.style.display = "none";
      downloadBtn.onclick = null;
    }
  }
}
